import itertools
import json
import math
import platform
import time
from collections import Counter
from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version

import numpy as np
from scipy.optimize import minimize
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator


CITY_VERTICES = ("C0", "C1", "C2", "C3", "C4", "C5", "C6", "C7", "C8")
CITY_COORDINATES_KM = {
    "C0": (0.0, 0.0),
    "C1": (3.0, 0.0),
    "C2": (6.0, 0.0),
    "C3": (0.0, 3.0),
    "C4": (3.0, 3.0),
    "C5": (6.0, 3.0),
    "C6": (0.0, 6.0),
    "C7": (3.0, 6.0),
    "C8": (6.0, 6.0),
}
CITY_EDGES = (
    ("C0", "C1"), ("C1", "C2"),
    ("C3", "C4"), ("C4", "C5"),
    ("C6", "C7"), ("C7", "C8"),
    ("C0", "C3"), ("C3", "C6"),
    ("C1", "C4"), ("C4", "C7"),
    ("C2", "C5"), ("C5", "C8"),
)
CONNECTION_RADIUS_KM = 3.5


def build_road_network(vertices, coordinates_km, connection_radius_km=3.5):
    """Evaluate every unordered pair; never infer roads from grid adjacency."""
    vertices = list(vertices)
    radius = float(connection_radius_km)
    if not math.isfinite(radius) or radius < 0:
        raise ValueError("connection_radius_km must be finite and nonnegative.")
    if len(vertices) != len(set(vertices)):
        raise ValueError("Vertices must be unique.")

    coordinates = {}
    for vertex in vertices:
        point = tuple(float(value) for value in coordinates_km[vertex])
        if len(point) != 2 or not all(math.isfinite(value) for value in point):
            raise ValueError(f"Invalid two-dimensional coordinates for {vertex}.")
        coordinates[vertex] = point

    edges = []
    evaluations = []
    for u, v in itertools.combinations(vertices, 2):
        distance = math.dist(coordinates[u], coordinates[v])
        connected = distance <= radius
        evaluations.append({
            "cities": [u, v],
            "distance_km": distance,
            "connected": connected,
        })
        if connected:
            edges.append((u, v))

    return edges, evaluations


def _positive_integer(value, name):
    if isinstance(value, (bool, np.bool_)) or not isinstance(
        value, (int, np.integer)
    ):
        raise ValueError(f"{name} must be an integer.")
    value = int(value)
    if value <= 0:
        raise ValueError(f"{name} must be positive.")
    return value


def _canonical_mask(mask, n):
    """Remove region-label symmetry by assigning vertex 0 to region A."""
    return mask ^ ((1 << n) - 1) if mask & 1 else mask


def _reference_mask(reference, vertices):
    """
    Accept two vertex groups, a vertex-to-label mapping, a binary assignment
    in vertex order, or a single vertex group whose complement is the other.
    """
    if reference is None:
        return None

    n = len(vertices)
    vertex_set = set(vertices)

    if isinstance(reference, Mapping) and set(reference) == vertex_set:
        labels = list(reference.values())
        try:
            unique_labels = set(labels)
        except TypeError as exc:
            raise ValueError("Reference region labels must be hashable.") from exc
        if len(unique_labels) != 2:
            raise ValueError("The reference must contain exactly two regions.")
        first_label = reference[vertices[0]]
        mask = sum(
            1 << i for i, vertex in enumerate(vertices)
            if reference[vertex] != first_label
        )
    else:
        items = (
            list(reference.values())
            if isinstance(reference, Mapping)
            else list(reference)
        )
        is_binary = len(items) == n and all(
            isinstance(item, (int, np.integer, bool, np.bool_))
            and int(item) in (0, 1)
            for item in items
        )
        if is_binary:
            mask = sum(int(bit) << i for i, bit in enumerate(items))
        else:
            if all(isinstance(item, str) and item in vertex_set for item in items):
                group_a = items
                group_b = [v for v in vertices if v not in set(group_a)]
            elif len(items) == 2 and all(
                not isinstance(item, (str, bytes)) for item in items
            ):
                group_a, group_b = list(items[0]), list(items[1])
            else:
                raise ValueError("Unsupported known_reference_partition format.")

            a, b = set(group_a), set(group_b)
            if (
                len(a) != len(group_a)
                or len(b) != len(group_b)
                or a & b
                or a | b != vertex_set
                or not a
                or not b
            ):
                raise ValueError(
                    "Reference regions must be nonempty, disjoint, and cover "
                    "every vertex exactly once."
                )
            mask = sum(1 << i for i, vertex in enumerate(vertices) if vertex in b)

    if mask in (0, (1 << n) - 1):
        raise ValueError("The reference partition must have two nonempty regions.")
    return _canonical_mask(mask, n)


def _natural_split_families(vertices):
    """Identify straight row/column cuts; all remaining bipartitions are mixed."""
    if set(vertices) != set(CITY_VERTICES):
        return {}

    families = {}
    for axis, name in ((1, "row_split"), (0, "column_split")):
        levels = sorted({CITY_COORDINATES_KM[v][axis] for v in vertices})
        for lower, upper in zip(levels[:-1], levels[1:]):
            boundary = (lower + upper) / 2.0
            mask = sum(
                1 << i for i, vertex in enumerate(vertices)
                if CITY_COORDINATES_KM[vertex][axis] > boundary
            )
            families[_canonical_mask(mask, len(vertices))] = name
    return families


def _partition_record(mask, vertices, edge_indices, degrees,
                      lambda_balance, lambda_cut, family):
    n = len(vertices)
    region_a = [v for i, v in enumerate(vertices) if not (mask >> i) & 1]
    region_b = [v for i, v in enumerate(vertices) if (mask >> i) & 1]
    cut = sum(((mask >> u) ^ (mask >> v)) & 1 for u, v in edge_indices)
    imbalance = abs(len(region_a) - len(region_b))
    volume_b = sum(degrees[i] for i in range(n) if (mask >> i) & 1)
    volume_a = sum(degrees) - volume_b
    m = len(edge_indices)

    # Newman-Girvan modularity for two communities in an undirected graph.
    modularity = (
        1.0 - cut / m
        - (volume_a / (2.0 * m)) ** 2
        - (volume_b / (2.0 * m)) ** 2
        if m else 0.0
    )

    # An isolated, zero-volume region contributes zero because its cut is zero.
    normalized_cut = (
        (cut / volume_a if volume_a else 0.0)
        + (cut / volume_b if volume_b else 0.0)
    )

    return {
        "partition_id": int(mask),
        "family": family,
        "regions": {"A": region_a, "B": region_b},
        "region_sizes": [len(region_a), len(region_b)],
        "region_volumes": [int(volume_a), int(volume_b)],
        "cut_edges": int(cut),
        "imbalance": int(imbalance),
        "weighted_cost": float(
            lambda_cut * cut + lambda_balance * imbalance ** 2
        ),
        "modularity_score": float(modularity),
        "normalized_cut_score": float(normalized_cut),
        "balance_constraint_score": float(1.0 - imbalance / n),
    }


def _candidate_key(record):
    # Only weighted cost is the primary objective. The remaining criteria
    # deterministically break ties between equally good weighted solutions.
    return (
        record["weighted_cost"],
        record["imbalance"],
        record["normalized_cut_score"],
        -record["modularity_score"],
        record["partition_id"],
    )


def _approximation_ratio(cost, optimum):
    """Minimization convention: achieved weighted cost / exact optimum >= 1."""
    if optimum == 0.0:
        return 1.0 if cost == 0.0 else None
    return float(cost / optimum)


def _local_refine(start_mask, records, n):
    """Deterministic descent using single-vertex moves and cross-region swaps."""
    current = start_mask
    full_mask = (1 << n) - 1
    while True:
        neighbors = {current}
        for i in range(n):
            trial = current ^ (1 << i)
            if trial not in (0, full_mask):
                neighbors.add(_canonical_mask(trial, n))
        for i, j in itertools.combinations(range(n), 2):
            if ((current >> i) & 1) != ((current >> j) & 1):
                trial = current ^ (1 << i) ^ (1 << j)
                if trial not in (0, full_mask):
                    neighbors.add(_canonical_mask(trial, n))

        best = min(neighbors, key=lambda mask: _candidate_key(records[mask]))
        if _candidate_key(records[best]) >= _candidate_key(records[current]):
            return current
        current = best


def _sample_counts(backend, parameterized_circuit, gammas, betas,
                   parameters, shots, seed):
    p = len(gammas)
    bindings = {
        **{gammas[i]: float(parameters[i]) for i in range(p)},
        **{betas[i]: float(parameters[p + i]) for i in range(p)},
    }
    bound = parameterized_circuit.assign_parameters(
        bindings, inplace=False, strict=False
    )
    result = backend.run(
        bound, shots=shots, seed_simulator=int(seed)
    ).result()
    if not result.success:
        raise RuntimeError(f"Aer simulation failed: {result.status}")

    # Qiskit displays classical bits most-significant first, so int(..., 2)
    # correctly maps qubit i to bit i of the integer assignment.
    return {
        int(bitstring.replace(" ", ""), 2): int(count)
        for bitstring, count in result.get_counts(0).items()
    }


def _environment_versions():
    versions = {"python": platform.python_version()}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy"):
        try:
            versions[package] = version(package)
        except PackageNotFoundError:
            versions[package] = "unavailable"
    return versions


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.4,
    lambda_cut=3.0,
    opt_shots=1024,
    final_shots=4096,
    maxiter=80,
    n_repro_runs=3,
    seed=42,
):
    """
    Shot-based QAOA + local refinement + exhaustive small-instance certification.

    Primary objective:
        F(A, B) = lambda_cut * cut(A, B)
                  + lambda_balance * (|A| - |B|)^2.

    Both regions must be nonempty. QAOA evolves the quadratic objective on the
    full Hilbert space; empty-region measurement outcomes are rejected when
    selecting partitions. Region connectivity is not an additional constraint.

    Every unlabeled nonempty bipartition is evaluated, including all straight
    row/column splits and every mixed split. For nine vertices this gives 255
    candidates. Exact enumeration supplies a certificate and, when necessary,
    an explicitly reported classical fallback; it is not a quantum speedup.

    Scores:
      modularity_score: standard undirected Newman-Girvan modularity.
      normalized_cut_score: cut/vol(A) + cut/vol(B), lower is better.
      balance_constraint_score: 1 - ||A|-|B||/n, higher is better.
        With nine vertices, its maximum is 8/9, not 1.
      approximation_ratio: returned F / exact minimum feasible F.
        This minimization ratio is 1 for a certified optimum. It is None when
        the optimum is zero but the compared solution has positive cost.
      runtime: total elapsed wall-clock seconds, excluding caller serialization.
      reproducibility: independent seeded-run results and replay information.

    The supplied reference is assessed but is not assumed optimal. Comparing
    cut counts alone would be misleading when the compared balances differ.

    Exact certification is intentionally limited to graphs with <=16 vertices.
    For the specified cities, the graph is reconstructed from all 36 distances,
    and supplied roads must agree with the 3.5 km geometric threshold.
    """
    started = time.perf_counter()

    vertices = list(graph_vertices)
    if not all(isinstance(v, str) for v in vertices):
        raise ValueError("Vertex labels must be strings.")
    if len(vertices) != len(set(vertices)):
        raise ValueError("Vertex labels must be unique.")
    n = len(vertices)
    if not 2 <= n <= 16:
        raise ValueError("This exhaustive-certification workflow requires 2–16 vertices.")

    p_layers = _positive_integer(p_layers, "p_layers")
    opt_shots = _positive_integer(opt_shots, "opt_shots")
    final_shots = _positive_integer(final_shots, "final_shots")
    maxiter = _positive_integer(maxiter, "maxiter")
    n_repro_runs = _positive_integer(n_repro_runs, "n_repro_runs")
    if isinstance(seed, (bool, np.bool_)) or not isinstance(seed, (int, np.integer)):
        raise ValueError("seed must be a nonnegative integer.")
    seed = int(seed)
    if seed < 0:
        raise ValueError("seed must be a nonnegative integer.")

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")

    index = {vertex: i for i, vertex in enumerate(vertices)}

    def normalize_edges(edges):
        normalized = set()
        for edge in edges:
            if len(edge) != 2:
                raise ValueError("Each road must have exactly two endpoints.")
            u, v = edge
            if u not in index or v not in index or u == v:
                raise ValueError(f"Invalid road: {edge!r}.")
            pair = tuple(sorted((index[u], index[v])))
            if pair in normalized:
                raise ValueError(f"Duplicate undirected road: {edge!r}.")
            normalized.add(pair)
        return normalized

    supplied_edges = None if graph_edges is None else normalize_edges(graph_edges)
    if set(vertices) == set(CITY_VERTICES):
        generated_edges, distance_evaluations = build_road_network(
            vertices, CITY_COORDINATES_KM, CONNECTION_RADIUS_KM
        )
        geometric_edges = normalize_edges(generated_edges)
        if supplied_edges is not None and supplied_edges != geometric_edges:
            raise ValueError(
                "graph_edges disagrees with the roads constructed from coordinates "
                "using the 3.5 km threshold."
            )
        edge_indices = sorted(geometric_edges)
        assert len(distance_evaluations) == 36
        assert len(edge_indices) == 12
        graph_report = {
            "constructed_from_coordinates": True,
            "coordinates_km": {
                vertex: list(CITY_COORDINATES_KM[vertex]) for vertex in vertices
            },
            "connection_radius_km": CONNECTION_RADIUS_KM,
            "pairwise_distances_evaluated": len(distance_evaluations),
            "pairwise_distances": distance_evaluations,
            "supplied_edges_verified": supplied_edges is not None,
        }
    else:
        if supplied_edges is None:
            raise ValueError("graph_edges is required for vertices without coordinates.")
        edge_indices = sorted(supplied_edges)
        graph_report = {
            "constructed_from_coordinates": False,
            "pairwise_distances_evaluated": 0,
        }

    graph_report.update({
        "vertices": vertices,
        "edges": [[vertices[u], vertices[v]] for u, v in edge_indices],
        "number_of_vertices": n,
        "number_of_edges": len(edge_indices),
    })
    graph_seconds = time.perf_counter() - started

    enumeration_started = time.perf_counter()
    degrees = [0] * n
    for u, v in edge_indices:
        degrees[u] += 1
        degrees[v] += 1

    families = _natural_split_families(vertices)
    full_mask = (1 << n) - 1

    # Even masks fix vertex 0 in A. Excluding zero excludes the trivial split;
    # the all-one assignment is already removed by region-label symmetry.
    records = {
        mask: _partition_record(
            mask, vertices, edge_indices, degrees,
            lambda_balance, lambda_cut, families.get(mask, "mixed_split"),
        )
        for mask in range(2, full_mask, 2)
    }
    assert len(records) == (1 << (n - 1)) - 1

    exact_mask = min(records, key=lambda mask: _candidate_key(records[mask]))
    exact_record = records[exact_mask]
    optimal_cost = exact_record["weighted_cost"]
    optimal_masks = {
        mask for mask, record in records.items()
        if record["weighted_cost"] == optimal_cost
    }

    reference_mask = _reference_mask(known_reference_partition, vertices)
    reference_report = None
    if reference_mask is not None:
        reference_report = dict(records[reference_mask])
        reference_report["approximation_ratio"] = _approximation_ratio(
            reference_report["weighted_cost"], optimal_cost
        )

    closest_imbalance = n % 2
    most_balanced = [
        record for record in records.values()
        if record["imbalance"] == closest_imbalance
    ]
    family_summary = {}
    for family in ("row_split", "column_split", "mixed_split"):
        candidates = [r for r in records.values() if r["family"] == family]
        family_summary[family] = {
            "number_evaluated": len(candidates),
            "best_candidate": min(candidates, key=_candidate_key) if candidates else None,
        }

    # Report the balance/cut Pareto frontier, rather than conflating unrestricted
    # minimum cut with the minimum cut achievable at the closest possible balance.
    tradeoffs = {}
    for mask, record in records.items():
        tradeoffs.setdefault(
            (record["cut_edges"], record["imbalance"]), []
        ).append(mask)
    pareto_front = []
    for (cut, imbalance), masks in sorted(tradeoffs.items()):
        dominated = any(
            other_cut <= cut
            and other_imbalance <= imbalance
            and (other_cut < cut or other_imbalance < imbalance)
            for other_cut, other_imbalance in tradeoffs
        )
        if not dominated:
            representative = min(masks, key=lambda mask: _candidate_key(records[mask]))
            pareto_front.append({
                "cut_edges": cut,
                "imbalance": imbalance,
                "number_of_partitions": len(masks),
                "representative": records[representative],
            })

    # Objective values for every computational-basis state, including trivial
    # assignments, are used for finite-shot expectation estimation.
    energies = np.empty(1 << n, dtype=float)
    for mask in range(1 << n):
        cut = sum(((mask >> u) ^ (mask >> v)) & 1 for u, v in edge_indices)
        imbalance = n - 2 * mask.bit_count()
        energies[mask] = (
            lambda_cut * cut + lambda_balance * imbalance * imbalance
        )
    if not np.all(np.isfinite(energies)):
        raise ValueError("Objective weights are too large for finite arithmetic.")
    enumeration_seconds = time.perf_counter() - enumeration_started

    compilation_started = time.perf_counter()
    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n)
    circuit.h(range(n))

    # With z_i = 1 - 2*x_i:
    # F = lambda_cut*m/2 + lambda_balance*n
    #     + sum_{i<j} [2*lambda_balance - lambda_cut*A_ij/2] Z_i Z_j.
    # RZZ(theta) = exp(-i theta Z_i Z_j / 2), hence theta = 2*gamma*J.
    # The constant contributes only a global phase and is omitted from gates.
    edge_set = set(edge_indices)
    couplings = [
        (
            i,
            j,
            2.0 * lambda_balance
            - (lambda_cut / 2.0 if (i, j) in edge_set else 0.0),
        )
        for i, j in itertools.combinations(range(n), 2)
    ]
    for layer in range(p_layers):
        for i, j, coupling in couplings:
            if coupling != 0.0:
                circuit.rzz(2.0 * coupling * gammas[layer], i, j)
        for i in range(n):
            circuit.rx(2.0 * betas[layer], i)
    circuit.measure_all()

    backend = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    transpiler_seed = seed % (1 << 32)
    compiled_circuit = transpile(
        circuit,
        backend,
        optimization_level=1,
        seed_transpiler=transpiler_seed,
    )
    compilation_seconds = time.perf_counter() - compilation_started

    run_seed_sequences = np.random.SeedSequence(seed).spawn(n_repro_runs)
    run_reports = []

    for run_index, seed_sequence in enumerate(run_seed_sequences):
        run_started = time.perf_counter()
        initialization_seed, optimization_seed, sampling_seed = [
            int(value) for value in seed_sequence.generate_state(3, dtype=np.uint32)
        ]
        rng = np.random.default_rng(initialization_seed)
        initial_parameters = np.concatenate((
            rng.uniform(0.0, math.pi, p_layers),
            rng.uniform(0.0, math.pi / 2.0, p_layers),
        ))
        best_parameters = initial_parameters.copy()
        best_expectation = math.inf
        objective_calls = 0

        def objective(parameters):
            nonlocal best_parameters, best_expectation, objective_calls
            # Reusing the optimization seed makes each parameter evaluation
            # replayable and uses common random numbers across evaluations.
            counts = _sample_counts(
                backend, compiled_circuit, gammas, betas,
                parameters, opt_shots, optimization_seed,
            )
            expectation = sum(
                count * energies[mask] for mask, count in counts.items()
            ) / sum(counts.values())
            objective_calls += 1
            if expectation < best_expectation:
                best_expectation = float(expectation)
                best_parameters = np.asarray(parameters, dtype=float).copy()
            return float(expectation)

        optimization_started = time.perf_counter()
        optimization_result = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={
                "maxiter": maxiter,
                "rhobeg": 0.4,
                "tol": 1e-3,
                "disp": False,
            },
        )
        optimization_seconds = time.perf_counter() - optimization_started

        sampling_started = time.perf_counter()
        final_counts = _sample_counts(
            backend, compiled_circuit, gammas, betas,
            best_parameters, final_shots, sampling_seed,
        )
        sampling_seconds = time.perf_counter() - sampling_started

        feasible_counts = Counter()
        invalid_shots = 0
        for mask, count in final_counts.items():
            if mask in (0, full_mask):
                invalid_shots += count
            else:
                feasible_counts[_canonical_mask(mask, n)] += count
        valid_shots = sum(feasible_counts.values())

        sampled_mask = (
            min(feasible_counts, key=lambda mask: _candidate_key(records[mask]))
            if feasible_counts else None
        )
        refined_mask = (
            _local_refine(sampled_mask, records, n)
            if sampled_mask is not None else None
        )

        # This fallback is classical and explicitly identified in all reports.
        used_fallback = (
            refined_mask is None
            or records[refined_mask]["weighted_cost"] > optimal_cost
        )
        returned_mask = exact_mask if used_fallback else refined_mask
        sampled_record = records[sampled_mask] if sampled_mask is not None else None
        refined_record = records[refined_mask] if refined_mask is not None else None
        returned_record = records[returned_mask]
        optimal_shots = sum(feasible_counts[mask] for mask in optimal_masks)

        run_reports.append({
            "run_index": run_index,
            "seeds": {
                "initialization": initialization_seed,
                "optimization_simulator": optimization_seed,
                "final_sampling_simulator": sampling_seed,
                "transpiler": transpiler_seed,
            },
            "optimizer": {
                "method": "COBYLA",
                "success": bool(optimization_result.success),
                "message": str(optimization_result.message),
                "objective_evaluations": objective_calls,
                "initial_parameters": initial_parameters.tolist(),
                "best_parameters": {
                    "gammas": best_parameters[:p_layers].tolist(),
                    "betas": best_parameters[p_layers:].tolist(),
                },
                "best_shot_estimated_expectation": best_expectation,
                "optimization_shots_per_evaluation": opt_shots,
            },
            "final_sampling": {
                "shots": final_shots,
                "valid_shots": valid_shots,
                "invalid_empty_region_shots": invalid_shots,
                "distinct_feasible_partitions_observed": len(feasible_counts),
                "optimal_partition_probability": optimal_shots / final_shots,
                "optimal_probability_conditioned_on_feasibility": (
                    optimal_shots / valid_shots if valid_shots else None
                ),
                "shot_estimated_expectation": float(
                    sum(energies[mask] * count for mask, count in final_counts.items())
                    / final_shots
                ),
                "most_frequent_feasible_partitions": [
                    {"partition_id": mask, "count": count}
                    for mask, count in sorted(
                        feasible_counts.items(), key=lambda item: (-item[1], item[0])
                    )[:10]
                ],
            },
            "best_sampled_partition": sampled_record,
            "sampled_approximation_ratio": (
                _approximation_ratio(sampled_record["weighted_cost"], optimal_cost)
                if sampled_record is not None else None
            ),
            "locally_refined_partition": refined_record,
            "refined_approximation_ratio": (
                _approximation_ratio(refined_record["weighted_cost"], optimal_cost)
                if refined_record is not None else None
            ),
            "returned_partition": returned_record,
            "returned_approximation_ratio": _approximation_ratio(
                returned_record["weighted_cost"], optimal_cost
            ),
            "used_exhaustive_fallback": used_fallback,
            "selection_source": (
                "exhaustive_classical_fallback"
                if used_fallback else "qaoa_samples_with_classical_local_refinement"
            ),
            "runtime_seconds": time.perf_counter() - run_started,
            "optimization_seconds": optimization_seconds,
            "final_sampling_seconds": sampling_seconds,
        })

    best_run = min(
        run_reports, key=lambda report: _candidate_key(report["returned_partition"])
    )
    selected = best_run["returned_partition"]
    returned_ids = [
        report["returned_partition"]["partition_id"] for report in run_reports
    ]
    partition_frequencies = Counter(returned_ids)

    stability = {}
    for metric in (
        "weighted_cost",
        "cut_edges",
        "modularity_score",
        "normalized_cut_score",
        "balance_constraint_score",
    ):
        values = np.asarray(
            [report["returned_partition"][metric] for report in run_reports],
            dtype=float,
        )
        stability[metric] = {
            "mean": float(np.mean(values)),
            "population_standard_deviation": float(np.std(values)),
            "minimum": float(np.min(values)),
            "maximum": float(np.max(values)),
        }

    reproducibility = {
        "master_seed": seed,
        "number_of_runs": n_repro_runs,
        "seed_schedule": "NumPy SeedSequence(master_seed).spawn(number_of_runs)",
        "environment": _environment_versions(),
        "simulator": "qiskit_aer.AerSimulator(method='statevector')",
        "noise_model": None,
        "simulator_parallel_threads": 1,
        "fixed_seed_replay": {
            "expected_same_results_in_same_environment": True,
            "separate_identical_seed_replay_verified": False,
            "runtime_is_not_deterministic": True,
        },
        "independent_seed_partition_agreement_fraction": (
            max(partition_frequencies.values()) / n_repro_runs
        ),
        "fraction_agreeing_with_reported_partition": (
            partition_frequencies[selected["partition_id"]] / n_repro_runs
        ),
        "raw_qaoa_optimum_hit_fraction": sum(
            report["best_sampled_partition"] is not None
            and report["best_sampled_partition"]["partition_id"] in optimal_masks
            for report in run_reports
        ) / n_repro_runs,
        "post_local_refinement_optimum_hit_fraction": sum(
            report["locally_refined_partition"] is not None
            and report["locally_refined_partition"]["partition_id"] in optimal_masks
            for report in run_reports
        ) / n_repro_runs,
        "exhaustive_fallback_fraction": sum(
            report["used_exhaustive_fallback"] for report in run_reports
        ) / n_repro_runs,
        "certified_optimum_hit_fraction": sum(
            report["returned_partition"]["partition_id"] in optimal_masks
            for report in run_reports
        ) / n_repro_runs,
        "returned_metric_stability": stability,
        "runs": run_reports,
    }

    output = {
        "modularity_score": selected["modularity_score"],
        "normalized_cut_score": selected["normalized_cut_score"],
        "balance_constraint_score": selected["balance_constraint_score"],
        "approximation_ratio": _approximation_ratio(
            selected["weighted_cost"], optimal_cost
        ),
        "runtime": None,
        "reproducibility": reproducibility,
        "partition": selected["regions"],
        "selected_partition_details": selected,
        "selected_run_index": best_run["run_index"],
        "selection_source": best_run["selection_source"],
        "graph": graph_report,
        "objective": {
            "definition": (
                "lambda_cut * cross_boundary_edges "
                "+ lambda_balance * (region_A_size - region_B_size)^2"
            ),
            "lambda_balance": lambda_balance,
            "lambda_cut": lambda_cut,
            "balance_policy": "soft quadratic penalty; both regions must be nonempty",
            "region_connectivity_required": False,
            "minimum_achievable_imbalance": closest_imbalance,
            "maximum_balance_constraint_score": 1.0 - closest_imbalance / n,
            "approximation_ratio_definition": (
                "returned weighted cost / exact minimum feasible weighted cost"
            ),
            "ising_constant_offset": (
                lambda_cut * len(edge_indices) / 2.0 + lambda_balance * n
            ),
        },
        "quantum_circuit": {
            "qubits": n,
            "qaoa_layers": p_layers,
            "compiled_depth": int(compiled_circuit.depth()),
            "compiled_gate_counts": {
                str(gate): int(count)
                for gate, count in compiled_circuit.count_ops().items()
            },
        },
        "exact_certificate": {
            "unlabeled_nonempty_partitions_evaluated": len(records),
            "optimal_weighted_cost": optimal_cost,
            "number_of_weighted_optima": len(optimal_masks),
            "optimal_partition_ids": sorted(optimal_masks),
            "deterministic_representative_optimum": exact_record,
            "returned_solution_is_weighted_optimal": (
                selected["partition_id"] in optimal_masks
            ),
            "unrestricted_nonempty_minimum_cut": min(
                record["cut_edges"] for record in records.values()
            ),
            "minimum_cut_at_closest_possible_balance": min(
                record["cut_edges"] for record in most_balanced
            ),
            "candidate_families": family_summary,
            "cut_balance_pareto_frontier": pareto_front,
        },
        "known_reference_partition_evaluation": reference_report,
        "candidate_evaluations": list(records.values()),
        "runtime_breakdown_seconds": {
            "graph_validation_and_construction": graph_seconds,
            "exhaustive_evaluation": enumeration_seconds,
            "circuit_construction_and_compilation": compilation_seconds,
            "qaoa_and_refinement_runs": sum(
                report["runtime_seconds"] for report in run_reports
            ),
        },
    }
    output["runtime"] = float(time.perf_counter() - started)
    return output


def main():
    # A natural 3/6 row split is a reference, not an asserted optimum.
    # At the default weights it costs 3*3 + 0.4*3^2 = 12.6.
    # A minimum-cut 4/5 split costs 3*4 + 0.4*1^2 = 12.4.
    reference_partition = (
        ["C0", "C1", "C2"],
        ["C3", "C4", "C5", "C6", "C7", "C8"],
    )
    result = solve_graph_partition_qaoa(
        graph_vertices=CITY_VERTICES,
        graph_edges=CITY_EDGES,
        known_reference_partition=reference_partition,
        p_layers=2,
        lambda_balance=0.4,
        lambda_cut=3.0,
        opt_shots=1024,
        final_shots=4096,
        maxiter=80,
        n_repro_runs=3,
        seed=42,
    )
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()
